local Input = CS.UnityEngine.Input
local KeyCode = CS.UnityEngine.KeyCode
local Physics = CS.UnityEngine.Physics

---@type ParkourGameUtil
local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")
---@type ParkourGameMgr
local Mgr = import("Game.Activity.ParkourGame.ParkourGameMgr"):GetInstance()
---@type ParkourBuff.Magnet
local MagnetBuff = import("Game.Activity.ParkourGame.MainGame.Buff.Magnet")
---@type ParkourBuff.InvincibleDash
local InvincibleDashBuff = import("Game.Activity.ParkourGame.MainGame.Buff.InvincibleDash")
local Application = CS.UnityEngine.Application

---@class TestGame
local TestGame = Class("TestGame")

function TestGame:Update()

    if Application.isEditor then

        if Input.GetKeyDown("1") then
            local duration = ParkourGameUtil.Params.MagnetTime
            local range = ParkourGameUtil.Params.MagnetRange
            Mgr.player:AddBuff(MagnetBuff.New(duration,range))
        end
        
        if Input.GetKeyDown("2") then
            local duration = ParkourGameUtil.Params.InvincibleDashTime
            local speedRatio = ParkourGameUtil.Params.InvincibleDashSpeedRatio
            Mgr.player:AddBuff(InvincibleDashBuff.New(duration, speedRatio))
        end
        
        if Input.GetKeyDown("3") then
            Mgr.boss:OnHit()
        end
        
        if Input.GetKeyDown("4") then
            Mgr.player.invisibleSkill:AddEnergy()
        end
    
        if Input.GetKeyDown("5") then
            Physics.autoSimulation = false
        end
        
        if Input.GetKeyDown("6") then
            Physics.autoSimulation = true
        end

        if Input.GetKeyDown(KeyCode.I) then
            Mgr.debug.isInvincible = not Mgr.debug.isInvincible
            GameUtils.Toast( Mgr.debug.isInvincible and "测试: 无敌模式" or "测试: 普通模式" ) -- 飘字
        end

    end
end

return TestGame